// This one came round while the agent was not running. It is rolled on to its
// next time and recorded, rather than run hours late as though nothing had
// happened.
const job = $('Pick What Is Due').first().json;
const at = new Date();
const rule = {
  frequency: job.frequency, timeOfDay: job.timeOfDay, dayOfWeek: job.dayOfWeek,
  dayOfMonth: job.dayOfMonth, onDate: job.onDate, timezone: job.timezone,
